; b02_poll_ready -- Peri polls a status register until its ready bit, then reads the data
; Layer-2 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: the Poll Unit: mask, clear, arm, the evaluation on a successful read into PERI_RX_BUF[0]; BR.IF_READY
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: b02_poll_ready.expected.csv
.include "conf_defs.inc"
.include "conf_board.inc"                      ; the CSRs of the board: put YOUR addresses and bits there first
.service SID_POLL = 4
.devmap 0, I2C, 0x2B, DEV_POLL
.main
wait:
    BR.COND PERI_RESULT_VALID, take
    JMP wait
take:
    MOV PERI_RESULT_SLOT[0..1] -> MAIN_SCRATCHPAD[0..1]
    EXEC_CSR WRITE_SP RES + 0, len=2, ptr=0
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
.peri
    EXEC_CSR SET8 PERI_CTRL, PERI_RESET
    EXEC_CSR WRITE8 POLL_MASK, 0x01            ; ready = bit 0 of the status byte
poll:
    EXEC_CSR SET8 POLL_CTRL, POLL_CLEAR_W1P
    EXEC_CSR SET8 POLL_CTRL, POLL_ARM_W1P      ; the next successful READ into PERI_RX_BUF[0] is evaluated
    EXEC_XFER READ dev=DEV_POLL, addr=0x05, addrlen=1, ptr=0
    BR.IF_READY ready
    JMP poll
ready:
    EXEC_XFER READ dev=DEV_POLL, len=2, ptr=2, ext=[0x40]
    EXEC_PUB service=SID_POLL, src=2, len=2
phalt:
    JMP phalt
